#include "skcms.h"
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <cstring>
int main(int argc,char**argv){if(argc!=3)return 2;FILE*f=fopen(argv[1],"rb");if(!f)return 3;fseek(f,0,SEEK_END);long n=ftell(f);rewind(f);std::vector<unsigned char>b(n+4);fread(b.data(),1,n,f);fclose(f);int tag=atoi(argv[2]);skcms_ICCProfile p;if(!skcms_ParseWithA2BPriority(b.data(),n,&tag,1,&p))return 4;fprintf(stderr,"{\"hasA2B\":%s,\"inputChannels\":%u,\"matrixChannels\":%u,\"matrix\":[",p.has_A2B?"true":"false",p.A2B.input_channels,p.A2B.matrix_channels);for(int r=0;r<3;r++)for(int c=0;c<4;c++)fprintf(stderr,"%s%.10g",(r||c)?",":"",p.A2B.matrix.vals[r][c]);fprintf(stderr,"]}\n");float input[3];while(scanf("%f %f %f",input,input+1,input+2)==3){skcms_ICCProfile clut=p,mm=p;clut.A2B.matrix_channels=0;for(int c=0;c<3;c++){clut.A2B.output_curves[c].parametric=*skcms_Identity_TransferFunction();clut.A2B.output_curves[c].alias_of_table_entries=0;mm.A2B.output_curves[c].parametric=*skcms_Identity_TransferFunction();mm.A2B.output_curves[c].alias_of_table_entries=0;}float a[3],m[3],o[3];bool ok=skcms_Transform(input,skcms_PixelFormat_RGB_fff,skcms_AlphaFormat_Opaque,&clut,a,skcms_PixelFormat_RGB_fff,skcms_AlphaFormat_Opaque,skcms_XYZD50_profile(),1)&&skcms_Transform(input,skcms_PixelFormat_RGB_fff,skcms_AlphaFormat_Opaque,&mm,m,skcms_PixelFormat_RGB_fff,skcms_AlphaFormat_Opaque,skcms_XYZD50_profile(),1)&&skcms_Transform(input,skcms_PixelFormat_RGB_fff,skcms_AlphaFormat_Opaque,&p,o,skcms_PixelFormat_RGB_fff,skcms_AlphaFormat_Opaque,skcms_XYZD50_profile(),1);if(!ok)return 5;printf("%.10g %.10g %.10g %.10g %.10g %.10g %.10g %.10g %.10g\n",a[0],a[1],a[2],m[0],m[1],m[2],o[0],o[1],o[2]);}return 0;}
